export const STEP = 1 / 60;
export const PROFILE_ROWS = 16;
export const MAX_HEARTS = 3;
export const PASS_MOLD = 0.6;
export const PASS_WARDEN = 0.7;

export const PALETTE = {
  skyDay: '#f6eeda',
  skyDayTop: '#e9d9b0',
  skyNight: '#2c3550',
  skyNightTop: '#1d2440',
  ground: '#b98d5f',
