  { name: "The Warden's Brow", shape: { base: 0.4, belly: 0.5, at: 0.35, rim: 0.5 }, moldTime: 25 },
  { name: "The Warden's Core", shape: { base: 0.55, belly: 0.65, at: 0.55, rim: 0.7 }, moldTime: 25 },
];

export const GRID_COLS = 6;
